function renderSession(){const {session,current,pending}=sessionChoice();const badge=$('sim-status-badge');if(badge){badge.classList.toggle('running',current&&!session?.timerWaiting&&!session?.timerWarmup);badge.classList.toggle('waiting',current&&(!!session?.timerWaiting||!!session?.timerWarmup));badge.classList.toggle('idle',!current);}const statusText=$('sim-status-text');if(statusText){statusText.textContent=current?(session?.timerWaiting?t('quest_wait_discord'):session?.timerWarmup?t('quest_preparing'):t('active_sim')):t('idle_sim');}const clockBadge=$('session-clock-badge');if(clockBadge){clockBadge.hidden=!current;if(current){const isRemaining=!!session?.remainingFormatted;if($('clock-type-label'))$('clock-type-label').textContent=t(isRemaining?'remaining':'elapsed');if($('idle-remaining-label'))$('idle-remaining-label').textContent=isRemaining?session.remainingFormatted:(session?.elapsedFormatted||'00:00:00');}}if($('sim-stopwatch-display'))$('sim-stopwatch-display').textContent=current?(session?.elapsedFormatted||'00:00:00'):'00:00:00';if($('remaining-clock'))$('remaining-clock').hidden=!current||!session?.remainingFormatted;if($('idle-progress-wrap'))$('idle-progress-wrap').hidden=!current||session?.progressPercent===null;if($('idle-progress-bar'))$('idle-progress-bar').style.width=(current?session?.progressPercent||0:0)+'%';
const canAppend=state.queue?.active&&!state.questQueue?.active;const invalidCustom=state.mode==='custom'&&!validCustomFilename(state.selectedExecutable);const activeDurationMinutes=session?(session.targetDurationSeconds?Math.round(session.targetDurationSeconds/60):0):null;const isDurationChanged=current&&activeDurationMinutes!==null&&state.durationMinutes!==activeDurationMinutes;const toggleBtn=$('btn-toggle-sim'),stopBtn=$('btn-stop-sim');if(current&&!isDurationChanged){toggleBtn.disabled=state.actionBusy||!!state.questQueue?.active;$('btn-sim-text').textContent=t('quest_stop');toggleBtn.classList.add('button-danger');setSlot('btn-sim-icon','square');if(stopBtn)stopBtn.hidden=true;}else if(current&&isDurationChanged){toggleBtn.disabled=state.actionBusy||!!state.questQueue?.active||!state.durationValid||invalidCustom;$('btn-sim-text').textContent=t('start_sim');toggleBtn.classList.remove('button-danger');setSlot('btn-sim-icon','play');if(stopBtn){stopBtn.hidden=false;stopBtn.disabled=state.actionBusy;setSlot('btn-stop-icon','square');}}else{toggleBtn.disabled=state.actionBusy||!!state.questQueue?.active||pending||(!current&&(!state.selectedGame||!state.durationValid||invalidCustom||((session||canAppend)&&state.durationMinutes<1)||(session&&!canAppend)));$('btn-sim-text').textContent=t(pending?'scheduled':session||canAppend?'play_next':'start_sim');toggleBtn.classList.remove('button-danger');setSlot('btn-sim-icon','play');if(stopBtn)stopBtn.hidden=true;}
$('session-pid-text').textContent='';const problem=current?activityProblem(session):state.queue?.phase==='error'?errorText(state.queue.error,'queue_error'):'';$('resolution-note').textContent=problem;$('resolution-note').hidden=!problem;$('selected-games-count').textContent=number(liveQueueCount());}
function validCustomFilename(value){const name=String(value||'').trim().replace(/\\/g,'/');return !!name&&new TextEncoder().encode(name).length<=240&&/\.(exe|bin)$/i.test(name)&&!/[<>:"|?*\x00-\x1f]/.test(name)&&name.split('/').every(part=>part&&part!=='.'&&part!=='..'&&!/[. ]$/.test(part)&&!/^(con|prn|aux|nul|com[1-9]|lpt[1-9])(?:\.|$)/i.test(part));}

function setSimulatorMode(mode){if(!['library','custom','selected'].includes(mode)||mode==='selected'&&liveQueueCount()<2)return;if(state.mode==='library'){state.librarySelection=state.selectedGame?.id==='999999999999999999'?null:state.selectedGame;state.libraryExecutable=state.selectedExecutable;state.libraryExplicitExecutable=!!state.explicitExecutable;}if(state.mode==='custom')state.customExecutable=$('custom-exe-input').value.trim();state.mode=mode;document.querySelectorAll('[data-sim-mode]').forEach(button=>button.classList.toggle('active',button.dataset.simMode===mode));$('simulation-workspace').hidden=mode==='selected';$('queue-panel').hidden=mode!=='selected';$('simulation-workspace').classList.toggle('custom-workspace',mode==='custom');document.querySelector('.games-panel').hidden=mode==='custom';$('sim-executable-select').closest('label').hidden=mode==='custom';$('save-override-btn').hidden=mode==='custom';if(mode==='custom'){selectGame({id:'999999999999999999',name:state.customExecutable.split(/[/\\]/).pop().replace(/\.exe$/i,'')||t('custom_process'),resolution:{executables:[],primaryExecutable:state.customExecutable||null,status:'custom'}});}else if(mode==='library'){selectGame(state.librarySelection||null);if(state.selectedGame&&state.libraryExecutable){state.selectedExecutable=state.libraryExecutable;state.explicitExecutable=!!state.libraryExplicitExecutable;renderSelected(true);}}renderSession();renderQueue();}
